export function isJsonEqual(a: unknown, b: unknown): boolean {
    if (a === b) return true;
    // eslint-disable-next-line no-restricted-syntax
    if (typeof a !== "object" || a === null || typeof b !== "object" || b === null) return false;
    // Option values hand this arrays, and Adamic checks that `object as MapLike<unknown>` views a record (#2v3xtgm), so
    // an array is compared here and never cast. Each answer is the one equalOwnProperties gives for an array holding
    // every index below its length and no other key, as JSON and the command line make every array. An array's own
    // enumerable keys are its indices, and its own keys add "length", which equalOwnProperties' second loop tests for
    // presence alone. That answer is asymmetric, so every comparison keeps the left side first.
    if (isArray(a) && isArray(b)) return a.length === b.length && every(a, (element, index) => isJsonEqual(element, b[index]));
    if (isArray(a)) {
        const right = b as MapLike<unknown>;
        for (let index = 0; index < a.length; index++) {
            if (!hasProperty(right, String(index)) || !isJsonEqual(a[index], right[String(index)])) return false;
        }
        for (const key in right) {
            if (hasProperty(right, key) && key !== "length" && !isIndexBelow(key, a.length)) return false;
        }
        return true;
    }
    if (isArray(b)) {
        const left = a as MapLike<unknown>;
        for (const key in left) {
            if (!hasProperty(left, key)) continue;
            if (key === "length") {
                if (!isJsonEqual(left[key], b.length)) return false;
            }
            else if (!isIndexBelow(key, b.length) || !isJsonEqual(left[key], b[Number(key)])) return false;
        }
        for (let index = 0; index < b.length; index++) {
            if (!hasProperty(left, String(index))) return false;
        }
        return true;
    }
    return equalOwnProperties(a as MapLike<unknown>, b as MapLike<unknown>, isJsonEqual);

    // isIndexBelow is whether key names an element of an array of that length: an integer below the length, spelled
    // as the array spells its own indices.
    function isIndexBelow(key: string, length: number) {
        const index = Number(key);
        return Number.isInteger(index) && index >= 0 && index < length && String(index) === key;
    }
}

